      SUBROUTINE REPAIR      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1B.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ICOPY.CIN'      INCLUDE 'LIMITS.CIN'      INCLUDE 'RDCARD.CIN'C      CHARACTER*15  BLANK, LABTYP      INTEGER       TYPC      EQUIVALENCE   (FAKE,LAKE)      DATA          BLANK /' '/C      CALL EXILEC      ISTOR(1) = 1      NUM = NELLIM - NEL + 1      IF (NUM .GT. NELLIM) GO TO 5400      NDIF = 1      NEL = 0      I = 1      IREFF = 1      NDEF = 0C   50 II = ISTOR(NUM)      TYPE = IDATA(II)      LABLE = LABEL(NUM)      NPARMS = 0      CALL SKETCH(NUM)      NPOLD = NPARMSC            IF (TYPE .EQ. 24) GO TO 2400      IF (TYPE .EQ. 49) GO TO 5300      IF (TYPE .EQ. 55) GO TO 5300      IF (TYPE .EQ. 56) GO TO 5300      GO TO 5010CC     24. -- DEFINED SECTIONC 2400 IF (NUM .EQ. NUSE) THEN        NUSE = NEL + 1      ENDIF      JDEF = IDATA(II+1)      IF (JDEF .EQ. 1) NDEF = NDEF + 1      IF (JDEF .EQ. 2) NDEF = NDEF - 1      GO TO 5010  CC     COPY ELEMENT POINTERS AND LABELS TO LIST AT BEGINNING C     OF DATA ARRAYC 5010 NEL = NEL + 1      IF (NUSE .EQ. 0 .OR. NDEF .EQ. 0 .OR. TYPE .EQ. 9     1    .OR. TYPE .EQ. 24 .OR. TYPE .EQ. 32) THEN        ISTOR(NEL) = I      ELSE        ISTOR(NEL) = ISTOR(NUM)      ENDIF      LABEL(NEL) = LABEL(NUM)      NDESCR(NEL) = NDESCR(NUM)      NDEFT = NDEF      IF (TYPE .EQ. 24) THEN        IF (JDEF .EQ. 1) NDEFT = 0        GO TO 5020      ENDIF      IF (NUSE .NE. 0 .AND. NDEFT .GT. 0 .AND. TYPE .NE. 9      1    .AND. TYPE .NE. 32) GO TO 5300CC     ELEMENT DEFINITION, COPY TO LOWER PLACE IN DATA ARRAYC 5020 NP1 = NPOLD + 1      IORIG = I      DO 5030 J = 1, NP1      I1 = II + J - 1      DATA(I) = DATA(I1)      TIE(I) = TIE(I1)      I = I + 1 5030 CONTINUE      ICOPY = I1      IF (NPARMS .GT. NPOLD) THEN        NP2 = NP1 + 1        NP1 = NPARMS + 1        DO 5040 J = NP2, NP1        DATA(I) = 0.0        TIE(I) = 0        I = I + 1 5040   CONTINUE      ENDIF      IF (TYPE .EQ. 9 .OR. TYPE .EQ. 24 .OR. TYPE .EQ. 32) GO TO 5300CC     FIND PRECEDING USE OF ELEMENTSC 5100 IF (LABLE .EQ. BLANK) GO TO 5140      NN = 0      NDEFI = 0C 5110 NN = NN + 1      III = ISTOR(NN)      TYPC = IDATA(III)      LABTYP = LABEL(NN)      IF (TYPC .EQ. 24) THEN        JDEF = IDATA(III+1)        IF (JDEF .EQ. 1) NDEFI = NDEFI + 1        IF (JDEF .EQ. 2) NDEFI = NDEFI - 1      ENDIF      IF (LABTYP .EQ. LABLE .AND. TYPC .EQ. TYPE) THEN        IF (NDEFI .EQ. 0) THEN          IF (NDEF .EQ. 0 .AND. NN .NE. NEL) GO TO 5120          ISTOR(NN) = ISTOR(NEL)          NDESCR(NN) = NDESCR(NEL)          LABEL(NN) = LABEL(NEL)        ENDIF      ENDIF 5120 IF (NN .LT. NEL - 1) GO TO 5110CC     FIND FOLLOWING USE OF ELEMENTSC 5140 IF (LABLE .EQ. BLANK) GO TO 5200      IF (NUM .GE. NELLIM) GO TO 5200      NN = NUM      NDEFI = NDEFC 5150 NN = NN + 1      III = ISTOR(NN)      TYPC = IDATA(III)      LABTYP = LABEL(NN)      IF (TYPC .EQ. 24) THEN        JDEF = IDATA(III+1)        IF (JDEF .EQ. 1) NDEFI = NDEFI + 1        IF (JDEF .EQ. 2) NDEFI = NDEFI - 1      ENDIF      IF (LABTYP .EQ. LABLE .AND. TYPC .EQ. TYPE) THEN        IF (NDEFI .NE. 0) THEN          ISTOR(NN) = ISTOR(NEL)          NDESCR(NN) = NDESCR(NEL)          LABEL(NN) = LABEL(NEL)        ENDIF      ENDIF      IF (NN .LT. NELLIM) GO TO 5150CC     REVISE PRECEDING REFERENCES TO A PARAMETERC 5200 IF (NUSE .NE. 0 .AND. NDEF .NE. 0) GO TO 5300      IF (NEL .LE. 1) GO TO 5250C     IF (II + NPARMS .LT. IREF) GO TO 5300      IP = 0C 5220 IP = IP + 1C     IF (II + IP .LT. IREF .AND. IP .LT. NPOLD) GO TO 5220      IIP = II + IP      NN = 0      NDEFI = 0C 5230 NN = NN + 1      III = IABS(ISTOR(NN))      IIJ = IABS(ISTOR(NN+1)) - 1      TYPC = IDATA(III)      IF (TYPC .EQ. 24) THEN        JDEF = IDATA(III+1)        IF (JDEF .EQ. 1 .OR. JDEF .EQ. 2) THEN          IF (JDEF .EQ. 1) NDEFI = NDEFI + 1          IF (JDEF .EQ. 2) NDEFI = NDEFI - 1        ENDIF      ENDIF      IF (NDEFI .NE. 0) GO TO 5237      IPT = 0      IPMAX = IIJ - III + 1 5235 IPT = IPT + 1      IIN = III + IPT      IF (TIE(IIN) .EQ. 100) THEN        IF (IDATA(IIN) .EQ. IIP) THEN          LAKE = IORIG + IP          DATA(IIN) = FAKE        ENDIF      ENDIF      IF (IPT .LT. IPMAX) GO TO 5235 5237 IF (NN .LT. NEL - 1) GO TO 5230      NN = NN + 1      III = IABS(ISTOR(NN))      TYPC = IDATA(III)      IF (TYPC .EQ. 24) THEN        JDEF = IDATA(III+1)        IF (JDEF .EQ. 1 .OR. JDEF .EQ. 2) THEN          IF (JDEF .EQ. 1) NDEFI = NDEFI + 1          IF (JDEF .EQ. 2) NDEFI = NDEFI - 1        ENDIF      ENDIF      IF (IP .LT. NPOLD) GO TO 5220CC     REVISE FOLLOWING REFERENCES TO A PARAMETERC 5250 IF (II + NPOLD .LT. IREFF) GO TO 5300       IP = 0      IREFN = IDLIM + 1C 5270 IP = IP + 1      IIP = II + IP      IF (IIP .LT. IREFF .AND. IP .LT. NPOLD) GO TO 5270      NDEFI = NDEFC      IF (NUM + 1 .GT. NELLIM) GO TO 5300      NN = NUMC 5280 NN = NN + 1      III = IABS(ISTOR(NN))      IF (NN .LT. NELLIM) THEN        IIJ = IABS(ISTOR(NN+1)) - 1      ELSE        IIJ = IDLIM      ENDIF      TYPC = IDATA(III)      IF (TYPC .EQ. 24) THEN        JDEF = IDATA(III+1)        IF (JDEF .EQ. 1 .OR. JDEF .EQ. 2) THEN          IF (JDEF .EQ. 1) NDEFI = NDEFI + 1          IF (JDEF .EQ. 2) NDEFI = NDEFI - 1        ENDIF      ELSE        IF (NUSE .NE. 0 .AND. NDEFI .NE. 0) GO TO 5295        IPT = 0        IPMAX = IIJ - III 5290   IPT = IPT + 1        IIN = III + IPT        IF (TIE(IIN) .EQ. 100) THEN          IF (IDATA(IIN) .EQ. IIP) THEN            LAKE = IORIG + IP            DATA(IIN) = FAKE          ENDIF          IDIIN = IDATA(IIN)          IF (IDIIN .LT. IREFN .AND. IDIIN .GT. II)      1        IREFN = IDIIN        ENDIF        IF (IPT .LT. IPMAX) GO TO 5290      ENDIF 5295 IF (NN .LT. NELLIM) GO TO 5280      IREFF = IREFN      IF (IREFF .GT. II + NPOLD) GO TO 5300       IF (IP .LT. NPOLD) GO TO 5270CC     PROCESS NEXT ELEMENTC 5300 NUM = NUM + 1      IF (NUM .LE. NELLIM) GO TO 50      ISTOR(NEL+1) = ICC     RETURNC 5400 CONTINUE      RETURN      END